Tính diện tích hình sau biết ${GH}=5cm$, ${FH}=12cm$, ${GE}=11cm$, ${FE}=6cm$
}{
\begin{tikzpicture}
    % Định nghĩa tọa độ của các điểm A và C (đường kính)
    \coordinate (A) at (0,0);
    \coordinate (C) at (6,0);
    \coordinate (B) at (1,2.236);  % Điểm B nằm trên đường tròn
    \coordinate (D) at (4,-2.828); % Điểm D nằm trên đường tròn

    \draw[blue, thick] (A) -- (B) -- (C) -- (D) -- cycle;

    \def\khvuong[size=#1](#2,#3,#4){%
        \draw ($(#3)!#1!(#2)$) --
        ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
        ($(#3)!#1!(#4)$);
    }
    \khvuong[size=7pt](C,B,A);
        \khvuong[size=7pt](C,D,A);
    \filldraw[black] (A) circle (2pt) node[below left] {$G$};
    \filldraw[black] (B) circle (2pt) node[above left] {$H$};
    \filldraw[black] (C) circle (2pt) node[below right] {$F$};
    \filldraw[black] (D) circle (2pt) node[below right] {$E$};
\end{tikzpicture}
}
\loigiai{ 
 Diện tích tam giác ${GHF}$ bằng $\dfrac{1}{2}GH.HF=\dfrac{1}{2}5.12=30cm^{2}$ 

Diện tích tam giác ${GEF}$ bằng $\dfrac{1}{2}GE.EF=\dfrac{1}{2}11.6=33cm^{2}$ 

 Diện tích của hình là $30cm^{2}+ 33cm^{2}=63cm^{2}$ 
 }\end{ex}

