\immini[thm]{
Vẽ tam giác đều có cạnh bằng ${4}cm$.
}{
\begin{tikzpicture}
    % Đặt các tọa độ cho các điểm A, B, C theo tỷ lệ nhỏ hơn
    \coordinate (B) at (0,0);   % Điểm B tại gốc tọa độ
    \coordinate (C) at (3,0);   % Điểm C cách B 3 đơn vị (thu nhỏ lại)
    \coordinate (A) at ($(B)!0.5!(C) + (0,2.6)$); % Điểm A tạo tam giác đều với BC

    % Vẽ các cạnh của tam giác ABC
    \draw[blue, thick] (A) -- (B) -- (C) -- cycle;

    % Vẽ 2 đường tròn đi qua A và B, và đi qua A và C
    \draw[green, thick] (B) circle (3cm);
    \draw[green, thick] (C) circle (3cm);

    % Đánh dấu các điểm A, B, C với chấm tròn nhỏ và tên
    \filldraw[red] (A) circle (2pt) node[above] {\textbf{A}};
    \filldraw[red] (B) circle (2pt) node[below left] {\textbf{B}};
    \filldraw[red] (C) circle (2pt) node[below right] {\textbf{C}};

    % Ghi nhãn độ dài cạnh BC
    \node at ($(B)!0.5!(C)$) [below] {$4cm$};

    \end{tikzpicture}
}
\loigiai{ 





 Vẽ đường thẳng $BC=4cm$, vẽ đường tròn tâm $B$ bán kính ${4}cm$ và đường tròn tâm $C$ bán kính ${4}cm$, hai đường tròn cắt nhau tại ${A}$. Nối 3 điểm ta được tam giác đều ${ABC}$. 
 }\end{ex}

